def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "plant_seeds_field1": And([
            self.field_is_fallow(self.field1),  # Field1 is designated as fallow
            self.robot_has_sensors,  # Robot has detection capability
            self.farm_has_active_fields  # Alternative fields are available
        ]),  # Planting in fallow field causes soil degradation
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
